//! Writes the synthetic fixtures generated by our own format writers.
//!
//! Usage: `glasnost-fixtures [OUT_DIR]` (default: tests/fixtures/synthetic).

use std::path::PathBuf;
use std::process::ExitCode;

fn main() -> ExitCode {
    let out = std::env::args_os().nth(1).map_or_else(
        || PathBuf::from(glasnost_tools::DEFAULT_FIXTURE_DIR),
        PathBuf::from,
    );
    match glasnost_tools::write_fixtures(&out) {
        Ok(n) => {
            println!("wrote {n} fixture(s) and the manifest to {}", out.display());
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("glasnost-fixtures: {e}");
            ExitCode::FAILURE
        }
    }
}
